package com.bank.composite.repository;

import com.bank.composite.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import java.time.LocalDateTime;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, String> {

    // USES ix_acct_date: equality on leading column + range on second column
    List<Transaction> findByAccountIdAndCreatedAtBetween(
            String accountId, LocalDateTime from, LocalDateTime to);

    // USES ix_acct_date (left prefix): equality on leading column alone
    List<Transaction> findByAccountId(String accountId);

    // DOES NOT use ix_acct_date efficiently: filters only the SECOND column
    // → falls back to a scan because of the left-prefix rule
    List<Transaction> findByCreatedAtBetween(LocalDateTime from, LocalDateTime to);
}
