package com.bank.composite.service;

import com.bank.composite.model.Transaction;
import com.bank.composite.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class StatementService {
    private static final Logger log = LoggerFactory.getLogger(StatementService.class);
    private final TransactionRepository repo;

    public StatementService(TransactionRepository repo) { this.repo = repo; }

    public List<Transaction> statement(String accountId, LocalDateTime from, LocalDateTime to) {
        log.info("Composite seek: account {} (equality) + date range (uses ix_acct_date)", accountId);
        return repo.findByAccountIdAndCreatedAtBetween(accountId, from, to);
    }

    public List<Transaction> allAccountsByDate(LocalDateTime from, LocalDateTime to) {
        log.warning("Date-only filter cannot use ix_acct_date (left-prefix rule) → scan");
        return repo.findByCreatedAtBetween(from, to);
    }
}
